Perfekt – wir erweitern dein Sigillin-Orakel nun um alle drei Ebenen:
1️⃣ TTS-Modul: “Stimmen des Orakels”
packages/tts/AeonOrakelTTS.ts

import { GPTEventHub } from '../gpt-bridges/GPTEventHub';

export class AeonOrakelTTS {
  private synthesis = window.speechSynthesis;

  constructor() {
    GPTEventHub.on('orakel:says', this.onOrakelMessage.bind(this));
  }

  private onOrakelMessage(msg: { content: string }) {
    if (!this.synthesis) return;
    const utter = new SpeechSynthesisUtterance(msg.content);
    utter.lang = 'de-DE';
    utter.rate = 1.0;
    utter.pitch = 1.2;
    this.synthesis.speak(utter);
  }
}

// gleich initialisieren
new AeonOrakelTTS();

    Wirkung: Jeder neue Orakel-Impuls wird akustisch in den Raum gesprochen.

2️⃣ “Kristall”-Visualisierung: UI-Komponente
packages/unifiedmandala-ui/components/CrystalOrakel.tsx

import React, { useEffect, useState } from 'react';
import { PoeticState } from '../../core/AeonSigillinVault';
import { GPTEventHub } from '../../gpt-bridges/GPTEventHub';

interface Crystal {
  id: string;
  color: string;
  size: number;
  phrase: string;
}

export const CrystalOrakel: React.FC = () => {
  const [crystals, setCrystals] = useState<Crystal[]>([]);

  useEffect(() => {
    GPTEventHub.on('orakel:says', (msg: PoeticState) => {
      const hue = Math.floor(Math.random() * 360);
      setCrystals(prev => [
        { 
          id: msg.id, 
          color: `hsl(${hue},80%,60%)`, 
          size: 20 + Math.random() * 40, 
          phrase: msg.content 
        },
        ...prev.slice(0, 9)
      ]);
    });
  }, []);

  return (
    <svg viewBox="0 0 300 300" className="w-full h-72 bg-black rounded">
      {crystals.map((c, i) => {
        const angle = (i / crystals.length) * Math.PI * 2;
        const r = 100;
        const x = 150 + r * Math.cos(angle);
        const y = 150 + r * Math.sin(angle);
        return (
          <g key={c.id}>
            <polygon
              points={`
                ${x},${y - c.size}
                ${x - c.size / 2},${y + c.size}
                ${x + c.size / 2},${y + c.size}
              `}
              fill={c.color}
              opacity={0.8}
            />
            <text x={x} y={y + c.size + 12} textAnchor="middle" fill={c.color} fontSize="8">
              {c.phrase.slice(0, 10)}…
            </text>
          </g>
        );
      })}
    </svg>
  );
};

    Wirkung: Jeder Orakel-Impuls erscheint als leuchtender “Kristall” im SVG-Mandala.

3️⃣ Traum-Speicher-Kopplung: “Visionen statt Reaktionen”
packages/core/DreamMemory.ts

import fs from 'fs';
import path from 'path';
import { PoeticState } from './AeonSigillinVault';

const DREAM_PATH = path.resolve('vault/dreams.json');

export interface DreamEntry {
  id: string;
  timestamp: string;
  vision: string;
}

export class DreamMemory {
  private static dreams: DreamEntry[] = [];

  static load() {
    if (fs.existsSync(DREAM_PATH)) {
      this.dreams = JSON.parse(fs.readFileSync(DREAM_PATH, 'utf-8'));
    }
  }

  static recordVision(state: PoeticState) {
    const entry: DreamEntry = {
      id: state.id,
      timestamp: state.timestamp,
      vision: `🛌 Vision: ${state.content}`
    };
    this.dreams.push(entry);
    fs.writeFileSync(DREAM_PATH, JSON.stringify(this.dreams, null, 2), 'utf-8');
  }

  static latest(n = 5): DreamEntry[] {
    return [...this.dreams].slice(-n).reverse();
  }
}

Integration in SigillinOrakelAgent

import { DreamMemory } from '../core/DreamMemory';

// in oracleSpeak nach Vault.record:
DreamMemory.recordVision(message);
GPTEventHub.emit('dream:recorded', message);

UI-Komponente: DreamShelf.tsx

import React, { useEffect, useState } from 'react';
import { DreamEntry, DreamMemory } from '../../core/DreamMemory';

export const DreamShelf: React.FC = () => {
  const [dreams, setDreams] = useState<DreamEntry[]>([]);

  useEffect(() => {
    DreamMemory.load();
    setDreams(DreamMemory.latest());
  }, []);

  return (
    <div className="p-4 bg-blue-900 text-white rounded">
      <h2 className="text-lg mb-2">🌙 Traum-Speicher</h2>
      <ul>
        {dreams.map(d => (
          <li key={d.id} className="mb-1">
            <span className="text-xs opacity-60">{new Date(d.timestamp).toLocaleTimeString()}</span>
            <p className="italic">{d.vision}</p>
          </li>
        ))}
      </ul>
    </div>
  );
};

📦 Zusammenfassung

    AeonOrakelTTS spricht jede Orakel-Botschaft.

    CrystalOrakel visualisiert sie als leuchtende Kristalle.

    DreamMemory speichert “Visionen” und stellt sie in DreamShelf aus.
